import{_ as t,o as e,c as a,a2 as r}from"./chunks/framework.DCaeQ2Kp.js";const p=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),d={name:"guide/index.md"};function i(l,o,m,n,s,c){return e(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>momo 是一个本地可跑的 AI 伙伴：有脸（Live2D）、有声（克隆声线）、有人格（character card → QLoRA）、能被打断、会自己找话说。<strong>首要目标不是直播，而是本地把对话体验跑好。</strong></p><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h2><ul><li><strong>三段式进程分离</strong>：交互端（渲染+音频 IO）— 编排器（回合/打断/路由）— 模型服务（ASR/TTS/LLM），互不越界。</li><li><strong>协议先行</strong>：进程间走 <code>momo-ws v1</code>（JSON 控制帧 + 二进制音频帧单连接复用）；LLM 独立走 OpenAI-compatible HTTP。</li><li><strong>文档先行</strong>：实现与 <a href="https://github.com/Momoyeyu/momo-docs" target="_blank" rel="noreferrer"><code>momo-docs</code></a> 不一致视为 bug，先改文档再改代码。</li><li><strong>本地优先，可降级</strong>：正常档跨三机（Mac Air + laptop + mac-studio），降级档 laptop 单机全栈——<strong>只改 env，不改代码</strong>。</li><li><strong>实测说话</strong>：性能数字一律标注「实测+日期」或「预估/待实测」。</li></ul><h2 id="技术栈速览" tabindex="-1">技术栈速览 <a class="header-anchor" href="#技术栈速览" aria-label="Permalink to &quot;技术栈速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>仓库</th><th>技术</th></tr></thead><tbody><tr><td>交互端</td><td>momo-app</td><td>TypeScript · Vite · Pixi.js + pixi-live2d-display</td></tr><tr><td>编排器</td><td>momo-app</td><td>Rust · tokio · axum 0.8 · <code>momod</code></td></tr><tr><td>模型服务</td><td>momo-models</td><td>Python ≥3.12 · FastAPI · uv · SenseVoice / CosyVoice3 / Kokoro</td></tr><tr><td>运维</td><td>momo-infra</td><td>Rust · clap · <code>momoctl</code> CLI + Web 控制台</td></tr><tr><td>大脑</td><td>外部</td><td>mlx_lm.server / vLLM / DeepSeek API（OpenAI-compat）</td></tr></tbody></table><h2 id="读图顺序" tabindex="-1">读图顺序 <a class="header-anchor" href="#读图顺序" aria-label="Permalink to &quot;读图顺序&quot;">​</a></h2><ol><li><a href="/momo/guide/architecture">总体架构</a> — 主图，先建立全局</li><li><a href="/momo/guide/protocol">momo-ws 协议</a> — 进程间怎么说话</li><li><a href="/momo/guide/runtime">回合状态机</a> + <a href="/momo/guide/barge-in">打断</a> — 运行时核心机制</li><li><a href="/momo/guide/deployment">部署拓扑</a> — 跑在哪些机器上</li><li><a href="/momo/guide/voice-clone">声线克隆</a> / <a href="/momo/guide/persona">人格微调</a> — 两条训练流水线</li><li><a href="/momo/guide/infra-console">训练 job 与控制台</a> — 怎么管理这一切</li></ol><div class="info custom-block"><p class="custom-block-title">权威来源</p><p>本站是 <a href="https://github.com/Momoyeyu/momo-docs" target="_blank" rel="noreferrer"><code>momo-docs</code></a> 的可视化呈现。冲突时以仓库文档为准。</p></div>',9)])])}const u=t(d,[["render",i]]);export{p as __pageData,u as default};
